1	import { useEffect, useState, type CSSProperties } from "react";
2	import {
3	  Breadcrumb,
4	  BreadcrumbItem,
5	  BreadcrumbList,
6	  BreadcrumbPage,
7	  BreadcrumbSeparator,
8	} from "./Breadcrumb";
9	import { KeptFloating } from "./onboarding/KeptFloating";
10	import { MemoryMatch } from "./onboarding/MemoryMatch";
11	import { OnboardingMascot } from "./onboarding/OnboardingMascot";
12	import { preloadOnboardingPhotos } from "./onboarding/onboardingMedia";
13	import { ReadsPictures } from "./onboarding/ReadsPictures";
14	import { SplitText } from "./onboarding/SplitText";
15	
16	const STAGE_WIDTH = 960;
17	const STAGE_HEIGHT = 540;
18	const LAST_SCREEN = 4;
19	/**
20	 * Drawn size of the big cropped mascot at stage scale 1; the body is about 63% of it.
21	 * Its centre sits 0.2 of this from the window's side and bottom edges. The body
22	 * never shrinks below 0.237 of it, so the blob keeps bleeding off both edges
23	 * however it breathes and turns.
24	 */
25	const MASCOT_SIZE = 860;
26	/** Eyes stay turned toward each screen's text (yaw + is right, pitch + is up). */
27	const WELCOME_LOOK = { yaw: -15, pitch: 24 };
28	const FAREWELL_LOOK = { yaw: 30, pitch: 12 };
29	/** The big mascots run at this rate (1.8x slower), so they stay calm beside the text. */
30	const MASCOT_SPEED = 0.55;
31	
32	const welcomeFaces = ["neutre", "curieux", "heureux", "attentif"] as const;
33	const farewellFaces = ["heureux", "neutre", "fier", "timide"] as const;
34	
35	function fitScale() {
36	  return Math.min(1, window.innerWidth / STAGE_WIDTH, window.innerHeight / STAGE_HEIGHT);
37	}
38	
39	export function FirstRunOverlay({ onFinish }: { onFinish: () => void }) {
40	  const [screen, setScreen] = useState(0);
41	  const [scale, setScale] = useState(fitScale);
42	
43	  useEffect(() => {
44	    const update = () => setScale(fitScale());
45	    const onKeyDown = (event: KeyboardEvent) => {
46	      if (event.key === "Escape") onFinish();
47	    };
48	    window.addEventListener("resize", update);
49	    window.addEventListener("keydown", onKeyDown);
50	    return () => {
51	      window.removeEventListener("resize", update);
52	      window.removeEventListener("keydown", onKeyDown);
53	    };
54	  }, [onFinish]);
55	
56	  // First launch keeps the window hidden until this screen has painted, and
57	  // the later screens' photos decode meanwhile so none of them pop in.
58	  useEffect(() => {
59	    preloadOnboardingPhotos();
60	    let frame = requestAnimationFrame(() => {
61	      frame = requestAnimationFrame(
62	        () => void window.inkling?.windowControls.ready().catch(() => null),
63	      );
64	    });
65	    return () => cancelAnimationFrame(frame);
66	  }, []);
67	
68	  const advance = () => (screen === LAST_SCREEN ? onFinish() : setScreen(screen + 1));
69	
70	  const actions = (style: CSSProperties) => (
71	    <div className="first-run-actions" style={style}>
72	      <button type="button" className="first-run-primary" onClick={advance}>
73	        {screen === LAST_SCREEN ? "Open my library" : "Continue"}
74	      </button>
75	      {screen > 0 ? (
76	        <button type="button" className="first-run-quiet" onClick={() => setScreen(screen - 1)}>
77	          Back
78	        </button>
79	      ) : null}
80	      <button type="button" className="first-run-quiet" onClick={onFinish}>
81	        Skip
82	      </button>
83	    </div>
84	  );
85	
86	  const mascotSize = MASCOT_SIZE * scale;
87	
88	  return (
89	    <div
90	      className="first-run-overlay"
91	      role="dialog"
92	      aria-modal="true"
93	      aria-label="Welcome to inkling"
94	    >
95	      {/* The big mascot hangs off the window's corner, not the stage's, so it
96	          stays cropped by the window edge at any size. */}
97	      {screen === 0 ? (
98	        <OnboardingMascot
99	          key="welcome"
100	          size={mascotSize}
101	          faces={welcomeFaces}
102	          look={WELCOME_LOOK}
103	          speed={MASCOT_SPEED}
104	          style={{ right: -0.3 * mascotSize, bottom: -0.3 * mascotSize }}
105	        />
106	      ) : null}
107	      {screen === LAST_SCREEN ? (
108	        <OnboardingMascot
109	          key="farewell"
110	          size={mascotSize}
111	          faces={farewellFaces}
112	          look={FAREWELL_LOOK}
113	          speed={MASCOT_SPEED}
114	          style={{ left: -0.3 * mascotSize, bottom: -0.3 * mascotSize }}
115	        />
116	      ) : null}
117	
118	      <div
119	        key={screen}
120	        className={
121	          screen === 0 || screen === LAST_SCREEN ? "first-run-stage is-large" : "first-run-stage"
122	        }
123	        style={{ transform: `translate(-50%, -50%) scale(${scale})` }}
124	      >
125	        {screen === 0 ? (
126	          <>
127	            <SplitText
128	              text="Drop something in."
129	              className="first-run-headline"
130	              style={{ left: 72, top: 118 }}
131	            />
132	            <p className="first-run-body" style={{ left: 72, top: 203 }}>
133	              Paste a link, drop in a file, or grab a screenshot.
134	              <br />
135	              It&apos;s kept the moment it lands. No folders to pick.
136	            </p>
137	            <div className="first-run-keys" style={{ left: 72, top: 294 }}>
138	              <kbd>Ctrl</kbd>
139	              <kbd>V</kbd>
140	              <span>works anywhere in inkling</span>
141	            </div>
142	            {actions({ left: 72, top: 364 })}
143	          </>
144	        ) : null}
145	
146	        {screen === 1 ? (
147	          <>
148	            <KeptFloating />
149	            <SplitText
150	              text="Kept as it came."
151	              className="first-run-headline is-centered"
152	              style={{ top: 164 }}
153	            />
154	            <p className="first-run-body is-centered" style={{ top: 232 }}>
155	              Articles, photos, PDFs, quotes, notes and posts each get
156	              <br />
157	              their own card, right away. Reading and indexing happen
158	              <br />
159	              quietly while you keep going.
160	            </p>
161	            {actions({ top: 337, left: 0, right: 0, justifyContent: "center" })}
162	          </>
163	        ) : null}
164	
165	        {screen === 2 ? (
166	          <>
167	            <MemoryMatch />
168	            <SplitText
169	              text="Half a memory is enough."
170	              className="first-run-headline is-centered"
171	              style={{ top: 312 }}
172	              delay={0.4}
173	            />
174	            <p className="first-run-body is-centered" style={{ top: 376 }}>
175	              Describe it the way it comes back to you. Search runs on this
176	              <br />
177	              computer, so nothing you save leaves it.
178	            </p>
179	            {actions({ top: 449, left: 0, right: 0, justifyContent: "center" })}
180	          </>
181	        ) : null}
182	
183	        {screen === 3 ? (
184	          <>
185	            <ReadsPictures />
186	            <SplitText
187	              text="It reads your pictures, too."
188	              className="first-run-headline is-wrapped"
189	              style={{ left: 72, top: 92, width: 390 }}
190	              delay={0.45}
191	            />
192	            <p className="first-run-body" style={{ left: 72, top: 230 }}>
193	              Words inside screenshots, photos and PDFs are
194	              <br />
195	              searchable. Remember one word, find the whole
196	              <br />
197	              thing. All on this computer.
198	            </p>
199	            <div className="first-run-keys" style={{ left: 72, top: 336 }}>
200	              <kbd>Ctrl</kbd>
201	              <kbd>K</kbd>
202	              <span>to search from anywhere</span>
203	            </div>
204	            {actions({ left: 72, top: 386 })}
205	          </>
206	        ) : null}
207	
208	        {screen === LAST_SCREEN ? (
209	          <>
210	            <SplitText
211	              text="It's all yours."
212	              className="first-run-headline"
213	              style={{ left: 400, top: 112 }}
214	            />
215	            <p className="first-run-body" style={{ left: 400, top: 197 }}>
216	              Your library lives on this computer, not in an
217	              <br />
218	              account. Export a full copy whenever you like.
219	              <br />
220	              inkling only goes online to fetch the links you save.
221	            </p>
222	            <Breadcrumb className="first-run-crumb" style={{ left: 400, top: 318 }}>
223	              <BreadcrumbList>
224	                <BreadcrumbItem>Settings</BreadcrumbItem>
225	                <BreadcrumbSeparator />
226	                <BreadcrumbItem>Data</BreadcrumbItem>
227	                <BreadcrumbSeparator />
228	                <BreadcrumbItem>
229	                  <BreadcrumbPage>Export a copy</BreadcrumbPage>
230	                </BreadcrumbItem>
231	              </BreadcrumbList>
232	            </Breadcrumb>
233	            {actions({ left: 400, top: 376 })}
234	          </>
235	        ) : null}
236	      </div>
237	    </div>
238	  );
239	}
