1	import { useLayoutEffect, useRef } from "react";
2	import { prefersReducedMotion } from "../mascot/mascotStore";
3	import { onboardingPhotos } from "./onboardingMedia";
4	
5	type Layer = "far" | "mid" | "near";
6	type FloatCard = { src: string; layer: Layer; x: number; y: number; w: number; h: number };
7	
8	const p = onboardingPhotos;
9	
10	// Positions and sizes come straight from the "Onboarding 2 · Every kind of
11	// thing" board in Paper, in the 960x540 stage's own pixels.
12	const CARDS: FloatCard[] = [
13	  { src: p.deskPlant, layer: "far", x: 10, y: 80, w: 71, h: 71 },
14	  { src: p.record, layer: "far", x: 870, y: 74, w: 71, h: 71 },
15	  { src: p.sprig, layer: "far", x: 411, y: 12, w: 58, h: 87 },
16	  { src: p.pottery, layer: "mid", x: 206, y: 396, w: 89, h: 89 },
17	  { src: p.field, layer: "mid", x: 110, y: 129, w: 110, h: 73 },
18	  { src: p.daisy, layer: "mid", x: 668, y: 52, w: 94, h: 85 },
19	  { src: p.delphinium, layer: "mid", x: 702, y: 395, w: 67, h: 120 },
20	  { src: p.sea, layer: "near", x: 753, y: 170, w: 134, h: 89 },
21	  { src: p.vases, layer: "near", x: 797, y: 302, w: 95, h: 126 },
22	  { src: p.book, layer: "near", x: 523, y: 435, w: 134, h: 89 },
23	  { src: p.stairs, layer: "near", x: 281, y: 401, w: 98, h: 122 },
24	  { src: p.monstera, layer: "near", x: 67, y: 232, w: 89, h: 134 },
25	  { src: p.sketching, layer: "near", x: 245, y: 20, w: 110, h: 110 },
26	  { src: p.car, layer: "near", x: 513, y: 28, w: 134, h: 89 },
27	];
28	
29	/** How strongly each layer follows the pointer and drifts; near moves most. */
30	const DEPTH: Record<Layer, number> = { far: 0.3, mid: 0.6, near: 1 };
31	const PARALLAX_PX = 40;
32	const DRIFT_PX = 6;
33	/** The board's photos drawn this much larger, and pushed this much further out. */
34	const SIZE_SCALE = 1.5;
35	const SPREAD = 1.12;
36	/** One lap around the copy for the near layer; deeper layers lag behind. */
37	const LAP_SECONDS = 120;
38	const LAP_SPEED: Record<Layer, number> = { far: 0.6, mid: 0.8, near: 1 };
39	const CENTER = { x: 480, y: 270 };
40	/** The stage is wider than tall, so laps follow its 16:9 ellipse. */
41	const ASPECT = 960 / 540;
42	
43	/** Each card's centre relative to the stage centre, with x squashed to a circle. */
44	const ORBITS = CARDS.map((card) => {
45	  const u = ((card.x + card.w / 2 - CENTER.x) * SPREAD) / ASPECT;
46	  const v = (card.y + card.h / 2 - CENTER.y) * SPREAD;
47	  return { u, v, w: card.w * SIZE_SCALE, h: card.h * SIZE_SCALE };
48	});
49	
50	/** Where a card sits after `angle` radians of lap, in stage pixels (top-left). */
51	function orbitPosition(index: number, angle: number) {
52	  const { u, v, w, h } = ORBITS[index];
53	  const cos = Math.cos(angle);
54	  const sin = Math.sin(angle);
55	  return {
56	    x: CENTER.x + (u * cos - v * sin) * ASPECT - w / 2,
57	    y: CENTER.y + (u * sin + v * cos) - h / 2,
58	  };
59	}
