61	/**
62	 * Screen two's backdrop: photos floating at three depths around the copy, as
63	 * on the Paper board, slowly circling it counter-clockwise. Fancy Components' Parallax Floating drives it: the
64	 * pointer pulls near photos further than far ones, and each photo drifts on
65	 * its own slow path, Drift Wall style.
66	 *
67	 * One rAF loop writes transforms straight to the photos, so React renders this
68	 * once. The loop only lives while the screen is mounted; reduced motion gets
69	 * the board's still layout.
70	 */
71	export function KeptFloating() {
72	  const cardRefs = useRef<(HTMLImageElement | null)[]>([]);
73	
74	  useLayoutEffect(() => {
75	    if (prefersReducedMotion()) return;
76	
77	    const pointer = { x: 0, y: 0 };
78	    const eased = { x: 0, y: 0 };
79	    const onPointerMove = (event: PointerEvent) => {
80	      pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
81	      pointer.y = (event.clientY / window.innerHeight) * 2 - 1;
82	    };
83	    window.addEventListener("pointermove", onPointerMove);
84	
85	    let raf = 0;
86	    let start = 0;
87	    const tick = (ms: number) => {
88	      raf = requestAnimationFrame(tick);
89	      if (!start) start = ms;
90	      const seconds = (ms - start) / 1000;
91	      eased.x += (pointer.x - eased.x) * 0.06;
92	      eased.y += (pointer.y - eased.y) * 0.06;
93	      CARDS.forEach((card, index) => {
94	        const el = cardRefs.current[index];
95	        if (!el) return;
96	        const depth = DEPTH[card.layer];
97	        const driftX = Math.sin(seconds * 0.23 + index * 2.1) * DRIFT_PX * depth;
98	        const driftY = Math.cos(seconds * 0.31 + index * 1.3) * DRIFT_PX * depth;
99	        // Negative angles run counter-clockwise on screen (y points down).
100	        const lap = orbitPosition(
101	          index,
102	          (-seconds / LAP_SECONDS) * Math.PI * 2 * LAP_SPEED[card.layer],
103	        );
104	        const x = lap.x + driftX - eased.x * PARALLAX_PX * depth;
105	        const y = lap.y + driftY - eased.y * PARALLAX_PX * depth;
106	        el.style.transform = `translate3d(${x}px, ${y}px, 0)`;
107	      });
108	    };
109	    raf = requestAnimationFrame(tick);
110	    return () => {
111	      cancelAnimationFrame(raf);
112	      window.removeEventListener("pointermove", onPointerMove);
113	    };
114	  }, []);
115	
116	  return (
117	    <div className="kept-floating" aria-hidden="true">
118	      {CARDS.map((card, index) => (
119	        <img
120	          key={card.src}
121	          ref={(el) => {
122	            cardRefs.current[index] = el;
123	          }}
124	          className={`kept-photo is-${card.layer}`}
125	          src={card.src}
126	          alt=""
127	          draggable={false}
128	          style={orbitStyle(index)}
129	        />
130	      ))}
131	    </div>
132	  );
133	}
134	
135	/** The still layout: lap zero, also what reduced motion keeps. */
136	function orbitStyle(index: number) {
137	  const { x, y } = orbitPosition(index, 0);
138	  return {
139	    left: 0,
140	    top: 0,
141	    width: ORBITS[index].w,
142	    height: ORBITS[index].h,
143	    transform: `translate3d(${x}px, ${y}px, 0)`,
144	  };
145	}
